import { useState, useEffect, useCallback, useRef } from "react";
import { Card, CardContent } from "../components/ui/card";
import { Button } from "../components/ui/button";
import { Badge } from "../components/ui/badge";
import { Clock, ChefHat, CheckCircle2, RefreshCw, Printer, Volume2, VolumeX, Download } from "lucide-react";  // p338+p381+p390
import apiClient from "../lib/apiClient";
import { startRealtime, onEvent, stopRealtime } from "../lib/realtime";
import { toast } from "sonner";

// p306: شاشة مطبخ حية (KDS) — 3 أعمدة حسب الحالة + تحديث لحظي عبر SSE
const COLS = [
  { status: "pending", label: "جديد", color: "text-amber-600" },
  { status: "preparing", label: "قيد التحضير", color: "text-blue-600" },
  { status: "served", label: "جاهز", color: "text-emerald-600" },
];
// p338: هوية مصدر الطلب — تُفرّق QR الزبون عن النادل والكاشير والتوصيل والمطبخ
const SRC = {
  qr: { label: "QR زبون", cls: "bg-sky-600" },
  waiter: { label: "نادل", cls: "bg-violet-600" },
  pos: { label: "كاشير", cls: "bg-neutral-600" },
  kitchen: { label: "مطبخ", cls: "bg-emerald-700" },
  delivery: { label: "توصيل", cls: "bg-orange-600" },
};
const SRC_FILTERS = [
  { v: "all", label: "كل المصادر" },
  { v: "qr", label: "QR" },
  { v: "pos", label: "كاشير" },
  { v: "waiter", label: "نادل" },
  { v: "delivery", label: "توصيل" },
  { v: "kitchen", label: "مطبخ" },
];

const elapsedMin = (iso) => {
  if (!iso) return 0;
  const m = (Date.now() - new Date(iso).getTime()) / 60000;
  return Math.max(0, Math.floor(m));
};
export default function KitchenDisplayPage() {
  const [orders, setOrders] = useState([]);
  const [loading, setLoading] = useState(true);
  const [, setTick] = useState(0);
  const timer = useRef(null);
  // p338: طبع تلقائي + فلتر المصدر + تذكرة الطبع
  const [autoPrint, setAutoPrint] = useState(() => localStorage.getItem("kds_autoprint") === "1");
  const [soundOn, setSoundOn] = useState(() => localStorage.getItem("kds_sound") !== "0");  // p381
  const [srcFilter, setSrcFilter] = useState("all");
  // p473: بحث أرشيف المطبخ
  const [kdsQuery, setKdsQuery] = useState("");
  const [searching, setSearching] = useState(false);
  const [stats, setStats] = useState(null);  // p363: شريط أداء المطبخ
  const [ticket, setTicket] = useState(null);

  const printOrder = useCallback(async (orderId) => {
    try {
      const res = await apiClient.get("/restaurant/kitchen-orders?all=1");
      const o = (res.data || []).find((x) => x.id === orderId);
      if (!o) return;
      setTicket(o);
      setTimeout(() => { try { window.print(); } catch (e) {} }, 400);
    } catch (e) { /* الطبع التلقائي صامت */ }
  }, []);

  // p381: نغمة تنبيه المطبخ — WebAudio ثنائية النبرة، بلا ملفات صوتية
  const beep = useCallback(() => {
    try {
      const ctx = new (window.AudioContext || window.webkitAudioContext)();
      [880, 1320].forEach((f, i) => {
        const osc = ctx.createOscillator();
        const gain = ctx.createGain();
        osc.connect(gain); gain.connect(ctx.destination);
        osc.frequency.value = f; osc.type = "sine";
        const t0 = ctx.currentTime + i * 0.18;
        gain.gain.setValueAtTime(0.15, t0);
        gain.gain.exponentialRampToValueAtTime(0.001, t0 + 0.16);
        osc.start(t0); osc.stop(t0 + 0.16);
      });
      setTimeout(() => { try { ctx.close(); } catch (e) {} }, 800);
    } catch (e) { /* الصوت غير متاح في هذا المتصفح */ }
  }, []);

  // p386: نغمة تصعيد المتأخرات — ثلاثية تصاعدية تميّزها عن نغمة الطلب الجديد
  const lateBeep = useCallback(() => {
    try {
      const ctx = new (window.AudioContext || window.webkitAudioContext)();
      [660, 880, 1320].forEach((f, i) => {
        const osc = ctx.createOscillator();
        const gain = ctx.createGain();
        osc.connect(gain); gain.connect(ctx.destination);
        osc.frequency.value = f; osc.type = "sine";
        const t0 = ctx.currentTime + i * 0.16;
        gain.gain.setValueAtTime(0.18, t0);
        gain.gain.exponentialRampToValueAtTime(0.001, t0 + 0.15);
        osc.start(t0); osc.stop(t0 + 0.15);
      });
      setTimeout(() => { try { ctx.close(); } catch (e) {} }, 900);
    } catch (e) { /* الصوت غير متاح في هذا المتصفح */ }
  }, []);
  const lateAlerted = useRef(new Set());  // طلبات نُبّه عنها — لا تكرار

  const toggleAutoPrint = () => {
    const v = !autoPrint;
    setAutoPrint(v);
    localStorage.setItem("kds_autoprint", v ? "1" : "0");
    toast.success(v ? "الطبع التلقائي مفعّل — كل طلب جديد يُطبع فورًا" : "الطبع التلقائي متوقف");
  };
  const fetchOrders = useCallback(async () => {
    try {
      const res = await apiClient.get("/restaurant/kitchen-orders");
      setOrders(res.data || []);
      apiClient.get("/restaurant/kitchen-stats?days=1").then(r => setStats(r.data)).catch(() => {});  // p363
    } catch (e) { /* عرض خفيف: لا إزعاج عند فشل جلب دوري */ }
    finally { setLoading(false); }
  }, []);

  // p473: بحث في أرشيف الطلبات (all=1) بالرمز/الطاولة/الزبون/الهاتف — المسح يعيد العرض الحي
  const runKdsSearch = async () => {
    if (!kdsQuery.trim()) { setSearching(false); fetchOrders(); return; }
    try {
      const res = await apiClient.get(`/restaurant/kitchen-orders?all=1&search=${encodeURIComponent(kdsQuery.trim())}`);
      setOrders(res.data || []);
      setSearching(true);
    } catch (e) { toast.error("تعذر البحث"); }
  };
  const clearKdsSearch = () => { setKdsQuery(""); setSearching(false); fetchOrders(); };
  useEffect(() => {
    fetchOrders();
    startRealtime();
    const un1 = onEvent("kitchen_order.created", (payload) => {
      fetchOrders();
      if (autoPrint && payload?.order_id) printOrder(payload.order_id);  // p338
      // p381: تنبيه لحظي عند وصول طلب جديد — نغمة + منبثق قصير
      if (localStorage.getItem("kds_sound") !== "0") {
        beep();
        toast.success(`طلب جديد${payload?.code ? " " + payload.code : ""}${payload?.table_name ? " — " + payload.table_name : ""}`, { duration: 5000 });
      }
    });
    const un2 = onEvent("kitchen_order.updated", fetchOrders);
    const poll = setInterval(fetchOrders, 15000);
    timer.current = setInterval(() => setTick((t) => t + 1), 30000);
    return () => { un1 && un1(); un2 && un2(); clearInterval(poll); clearInterval(timer.current); stopRealtime(); };
  }, [fetchOrders, autoPrint, printOrder, beep]);  // p338+p381

  // p386: تصعيد صوتي للطلبات المتأخرة — كل طلب يتجاوز 15د بلا تقديم يُنبّه عنه مرة واحدة
  useEffect(() => {
    const ids = new Set();
    const fresh = [];
    (orders || []).forEach((o) => {
      if (o.status === "served" || o.status === "cancelled") return;
      if (elapsedMin(o.created_at) >= 15) {
        ids.add(o.id);
        if (!lateAlerted.current.has(o.id)) fresh.push(o);
      }
    });
    lateAlerted.current.forEach((id) => { if (!ids.has(id)) lateAlerted.current.delete(id); });
    if (!fresh.length) return;
    fresh.forEach((o) => lateAlerted.current.add(o.id));
    if (localStorage.getItem("kds_sound") === "0") return;
    lateBeep();
    toast.error(`طلب متأخر ≥15د${fresh[0]?.code ? " — " + fresh[0].code : ""}${fresh.length > 1 ? ` (+${fresh.length - 1})` : ""}`, { duration: 9000 });
    console.info("kds-late-escalation", fresh.map((o) => o.id).join(","));
  }, [orders, lateBeep]);
  const setStatus = async (o, status) => {
    try {
      await apiClient.put(`/restaurant/kitchen-orders/${o.id}/status`, { status });
      fetchOrders();
    } catch (e) { toast.error(e.response?.data?.detail || "تعذر تحديث الحالة"); }
  };
  // p390: تحميل تقرير أداء المطبخ PDF (نفس فترة شريط الإحصاءات: اليوم)
  const downloadStatsPdf = async () => {
    try {
      const res = await apiClient.get("/restaurant/kitchen-stats.pdf?days=1", { responseType: "blob" });
      const url = URL.createObjectURL(res.data);
      const a = document.createElement("a");
      a.href = url;
      a.download = "kitchen-stats-1d.pdf";
      document.body.appendChild(a);
      a.click();
      a.remove();
      setTimeout(() => URL.revokeObjectURL(url), 5000);
    } catch (e) { toast.error("تعذر تحميل PDF"); }
  };
  // p405: تصدير أداء المطبخ CSV (BOM عربي لـ Excel — نفس فترة زر PDF: اليوم)
  const downloadStatsCsv = async () => {
    try {
      const res = await apiClient.get("/restaurant/kitchen-stats.csv?days=1", { responseType: "blob" });
      const url = URL.createObjectURL(res.data);
      const a = document.createElement("a");
      a.href = url;
      a.download = "kitchen-stats-1d.csv";
      document.body.appendChild(a);
      a.click();
      a.remove();
      setTimeout(() => URL.revokeObjectURL(url), 5000);
    } catch (e) { toast.error("تعذر تحميل CSV"); }
  };
  // p456: حمل المطبخ حسب الساعة CSV (BOM عربي لـ Excel — آخر 30 يومًا)
  const downloadLoadCsv = async () => {
    try {
      const res = await apiClient.get("/restaurant/kitchen-load.csv?days=30", { responseType: "blob" });
      const url = URL.createObjectURL(res.data);
      const a = document.createElement("a");
      a.href = url;
      a.download = "kitchen-load-30d.csv";
      document.body.appendChild(a);
      a.click();
      a.remove();
      setTimeout(() => URL.revokeObjectURL(url), 5000);
    } catch (e) { toast.error("تعذر تحميل CSV"); }
  };

  // p438: تقرير الإلغاءات اليومي CSV (BOM عربي لـ Excel — آخر 30 يومًا)
  const downloadCxlCsv = async () => {
    try {
      const res = await apiClient.get("/restaurant/cancellations.csv?days=30", { responseType: "blob" });
      const url = URL.createObjectURL(res.data);
      const a = document.createElement("a");
      a.href = url;
      a.download = "cancellations-30d.csv";
      document.body.appendChild(a);
      a.click();
      a.remove();
      setTimeout(() => URL.revokeObjectURL(url), 5000);
    } catch (e) { toast.error("تعذر تحميل CSV"); }
  };

  // p426: أرشيف طلبات المطبخ CSV (BOM عربي لـ Excel — آخر 7 أيام)
  const downloadOrdersCsv = async () => {
    try {
      const res = await apiClient.get("/restaurant/kitchen-orders.csv?days=7", { responseType: "blob" });
      const url = URL.createObjectURL(res.data);
      const a = document.createElement("a");
      a.href = url;
      a.download = "kitchen-orders-7d.csv";
      document.body.appendChild(a);
      a.click();
      a.remove();
      setTimeout(() => URL.revokeObjectURL(url), 5000);
    } catch (e) { toast.error("تعذر تحميل CSV"); }
  };
  return (
    <div className="min-h-screen bg-background p-4 space-y-4" dir="rtl" data-testid="kds-page">
      <div className="flex items-center justify-between flex-wrap gap-2">
        <h1 className="text-2xl font-bold flex items-center gap-2"><ChefHat className="h-7 w-7" /> شاشة المطبخ</h1>
        <div className="flex items-center gap-2 flex-wrap">
          {/* p338: فلترة حسب مصدر الطلب */}
          <div className="flex gap-1">
            {SRC_FILTERS.map((f) => (
              <Button key={f.v} size="sm" variant={srcFilter === f.v ? "default" : "outline"}
                onClick={() => setSrcFilter(f.v)} data-testid={`kds-src-${f.v}`}>
                {f.label}
              </Button>
            ))}
          </div>
          <Button variant={autoPrint ? "default" : "outline"} size="sm" onClick={toggleAutoPrint} data-testid="kds-autoprint">
            <Printer className="h-4 w-4 ml-1" /> {autoPrint ? "الطبع التلقائي: مفعّل" : "الطبع التلقائي: متوقف"}
          </Button>
          <Button variant={soundOn ? "default" : "outline"} size="sm" data-testid="kds-sound-toggle"
            onClick={() => { const v = !soundOn; setSoundOn(v); localStorage.setItem("kds_sound", v ? "1" : "0"); toast.success(v ? "التنبيه الصوتي مفعّل" : "التنبيه الصوتي متوقف"); }}>
            {soundOn ? <Volume2 className="h-4 w-4 ml-1" /> : <VolumeX className="h-4 w-4 ml-1" />} {soundOn ? "الصوت: مفعّل" : "الصوت: متوقف"}
          </Button>
          <Button variant="outline" size="sm" onClick={fetchOrders} data-testid="kds-refresh">
            <RefreshCw className="h-4 w-4 ml-1" /> تحديث
          </Button>
        </div>
      </div>
      {stats && stats.count > 0 && (
        <div className="flex items-center gap-2 flex-wrap text-xs" data-testid="kds-stats">
          <Badge variant="secondary">اليوم: {stats.count} طلب</Badge>
          <Badge variant="secondary" data-testid="kds-stat-wait">انتظار {stats.avg_wait_min} د</Badge>
          <Badge variant="secondary" data-testid="kds-stat-prep">تحضير {stats.avg_prep_min} د</Badge>
          <Badge variant={stats.late_count > 0 ? "destructive" : "secondary"} data-testid="kds-stat-late">متأخر (≥15د): {stats.late_count}</Badge>
          {stats.slowest_dishes?.[0] && (
            <Badge variant="outline" className="border-amber-400 text-amber-700" data-testid="kds-slowest">
              أبطأ طبق: {stats.slowest_dishes[0].name} ({stats.slowest_dishes[0].avg_total_min} د)
            </Badge>
          )}
          <Button variant="outline" size="sm" className="h-6 px-2" data-testid="kds-stats-pdf" onClick={downloadStatsPdf} title="تقرير أداء المطبخ PDF">
            <Download className="h-3.5 w-3.5" />
          </Button>
          <Button variant="outline" size="sm" className="h-6 px-2 text-[10px]" data-testid="kds-stats-csv" onClick={downloadStatsCsv} title="تصدير CSV (Excel)">
            CSV
          </Button>
          <Button variant="outline" size="sm" className="h-6 px-2 text-[10px]" data-testid="kds-load-csv" onClick={downloadLoadCsv} title="حمل المطبخ حسب الساعة CSV (آخر 30 يومًا)">
            حمل
          </Button>
          <Button variant="outline" size="sm" className="h-6 px-2 text-[10px]" data-testid="kds-cancel-csv" onClick={downloadCxlCsv} title="تقرير الإلغاءات CSV (آخر 30 يومًا)">
            إلغاءات
          </Button>
          <Button variant="outline" size="sm" className="h-6 px-2 text-[10px]" data-testid="kds-orders-csv" onClick={downloadOrdersCsv} title="أرشيف الطلبات CSV (آخر 7 أيام)">
            أرشيف
          </Button>
          <input value={kdsQuery} onChange={(e) => setKdsQuery(e.target.value)} data-testid="kds-search-input"
            onKeyDown={(e) => { if (e.key === 'Enter') runKdsSearch(); }}
            className="h-6 px-2 text-[10px] border rounded-md bg-background w-28" placeholder="رمز/طاولة/زبون" title="بحث في أرشيف الطلبات" />
          <Button variant="outline" size="sm" className="h-6 px-2 text-[10px]" data-testid="kds-search-btn" onClick={runKdsSearch} title="بحث في الأرشيف">
            بحث
          </Button>
        </div>
      )}
      {searching ? (
        <div className="space-y-2" data-testid="kds-search-results">
          <div className="flex items-center gap-2">
            <p className="text-sm font-semibold">نتائج البحث ({orders.length})</p>
            <Button variant="outline" size="sm" className="h-6 px-2 text-[10px]" data-testid="kds-search-clear" onClick={clearKdsSearch}>مسح</Button>
          </div>
          {orders.length === 0 && <p className="text-xs text-muted-foreground">لا نتائج</p>}
          {orders.map((o) => (
            <div key={o.id} className="border rounded-md p-2 text-xs flex items-center justify-between" data-testid={`kds-sr-${o.id}`}>
              <span>{o.code || o.id} — {o.table_name || o.customer_name || "—"}</span>
              <Badge variant="secondary">{o.status}</Badge>
            </div>
          ))}
        </div>
      ) : loading ? <p className="text-muted-foreground">جارٍ التحميل...</p> : (
        <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
          {COLS.map((col) => {
            const list = orders.filter((o) => o.status === col.status && (srcFilter === 'all' || (o.source || 'pos') === srcFilter));  // p338
            return (
              <div key={col.status} className="space-y-3" data-testid={`kds-col-${col.status}`}>
                <h2 className={`font-semibold flex items-center gap-2 ${col.color}`}>
                  {col.label} <Badge variant="secondary">{list.length}</Badge>
                </h2>
                {list.length === 0 && <p className="text-xs text-muted-foreground">لا طلبات</p>}
                {list.map((o) => {
                  const mins = elapsedMin(o.created_at);
                  const late = col.status !== "served" && mins >= 15;
                  return (
                    <Card key={o.id} className={late ? "border-destructive" : ""} data-testid={`kds-order-${o.id}`}>
                      <CardContent className="p-3 space-y-2">
                        <div className="flex items-center justify-between">
                          <span className="font-bold">{o.code}</span>
                          <span className={`flex items-center gap-1 text-xs ${late ? "text-destructive font-bold" : "text-muted-foreground"}`}>
                            <Clock className="h-3 w-3" /> {mins} د
                          </span>
                        </div>
                        {/* p338: شارة المصدر + المنشئ + حالة الدفع */}
                        <div className="flex items-center gap-1.5 flex-wrap">
                          <span className="text-xs text-muted-foreground">الطاولة: {o.table_name || "—"}</span>
                          <span className={`text-[10px] text-white rounded-full px-2 py-0.5 font-bold ${(SRC[o.source] || SRC.pos).cls}`} data-testid={`kds-source-${o.id}`}>
                            {(SRC[o.source] || SRC.pos).label}{o.created_by && !["QR"].includes(o.created_by) ? `: ${o.created_by}` : ""}
                          </span>
                          {o.payment_status === "unpaid" && (
                            <span className="text-[10px] text-white rounded-full px-2 py-0.5 font-bold bg-red-600" data-testid={`kds-unpaid-${o.id}`}>غير مدفوع</span>
                          )}
                          {o.payment_status === "paid" && (
                            <span className="text-[10px] text-white rounded-full px-2 py-0.5 font-bold bg-emerald-600" data-testid={`kds-paid-${o.id}`}>مدفوع</span>
                          )}
                          {o.payment_status === "partial" && (
                            <span className="text-[10px] text-white rounded-full px-2 py-0.5 font-bold bg-amber-500" data-testid={`kds-partial-${o.id}`}>مدفوع جزئياً</span>
                          )}
                        </div>
                        <ul className="text-sm space-y-0.5">
                          {(o.items || []).map((it, i) => (
                            <li key={i} className="flex justify-between gap-2 border-b border-dashed last:border-0 pb-1">
                              <span>
                                {it.product_name}
                                {/* p338: الإضافات بأخضر والحذوفات/الملاحظات بأحمر — يراها الطاهي بوضوح */}
                                {(it.modifiers || []).length > 0 && (
                                  <span className="block text-xs font-bold text-emerald-700" data-testid={`kds-mods-${o.id}-${i}`}>
                                    {(it.modifiers || []).map((m) => `+ ${m.option}`).join(" · ")}
                                  </span>
                                )}
                                {it.note && (
                                  <span className="block text-xs font-bold text-red-600" data-testid={`kds-note-${o.id}-${i}`}>ملاحظة: {it.note}</span>
                                )}
                              </span>
                              <span className="font-mono">×{it.quantity}</span>
                            </li>
                          ))}
                        </ul>
                        {o.notes && <p className="text-xs text-amber-700 bg-amber-50 rounded p-1">{o.notes}</p>}
                        <div className="flex gap-2 pt-1">
                          {col.status === "pending" && (
                            <Button className="flex-1 min-h-[44px]" onClick={() => setStatus(o, "preparing")} data-testid={`kds-start-${o.id}`}>بدء التحضير</Button>
                          )}
                          {col.status === "preparing" && (
                            <Button className="flex-1 min-h-[44px] bg-emerald-600 hover:bg-emerald-700" onClick={() => setStatus(o, "served")} data-testid={`kds-ready-${o.id}`}>
                              <CheckCircle2 className="h-4 w-4 ml-1" /> جاهز
                            </Button>
                          )}
                          {col.status !== "served" && (
                            <Button variant="outline" className="min-h-[44px]" onClick={() => setStatus(o, "cancelled")} data-testid={`kds-cancel-${o.id}`}>إلغاء</Button>
                          )}
                        </div>
                      </CardContent>
                    </Card>
                  );
                })}
              </div>
            );
          })}
        </div>
      )}
      {/* p338: تذكرة الطبع التلقائي — مخفية على الشاشة، تظهر عند الطبع فقط */}
      {ticket && (
        <div id="kds-ticket" className="hidden print:block" dir="rtl" data-testid="kds-ticket">
          <style>{`@media print { body * { visibility: hidden; } #kds-ticket, #kds-ticket * { visibility: visible; } #kds-ticket { position: absolute; inset: 0; background: #fff; color: #000; padding: 24px; font-family: monospace; } }`}</style>
          <div style={{ textAlign: 'center', borderBottom: '2px dashed #000', paddingBottom: 8, marginBottom: 8 }}>
            <div style={{ fontSize: 22, fontWeight: 900 }}>طلب {ticket.code}</div>
            <div style={{ fontSize: 16 }}>الطاولة: {ticket.table_name || '—'} · المصدر: {(SRC[ticket.source] || SRC.pos).label}{ticket.created_by && ticket.created_by !== 'QR' ? ` · ${ticket.created_by}` : ''}</div>
            <div style={{ fontSize: 14 }}>{new Date(ticket.created_at).toLocaleString('ar-DZ')}</div>
          </div>
          <ul style={{ fontSize: 18, lineHeight: 1.9, listStyle: 'none', padding: 0 }}>
            {(ticket.items || []).map((it, i) => (
              <li key={i} style={{ borderBottom: '1px solid #ccc', padding: '4px 0' }}>
                <b>×{it.quantity}</b> {it.product_name}
                {(it.modifiers || []).map((m, j) => (<div key={j} style={{ fontSize: 15 }}>+ {m.option}{m.price_delta ? ` (+${m.price_delta})` : ''}</div>))}
                {it.note && <div style={{ fontSize: 15, fontWeight: 700 }}>ملاحظة: {it.note}</div>}
              </li>
            ))}
          </ul>
          {ticket.notes && <div style={{ border: '2px solid #000', padding: 8, marginTop: 8, fontWeight: 700 }}>ملاحظات الطلب: {ticket.notes}</div>}
          <div style={{ textAlign: 'center', marginTop: 10, fontSize: 16 }}>الإجمالي: {ticket.total ?? 0} دج</div>
        </div>
      )}
    </div>
  );
}
